validator:
function validate(input) {
  const [{ Delivery = [] }] = input;
  const ids = new Set();
  for (const row of Delivery) {
    if (row.some((v) => v === null)) return 'Delivery rows may not contain null.';
    if (ids.has(row[0])) return `delivery_id ${row[0]} appears twice in Delivery.`;
    ids.add(row[0]);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(row[2]) || !/^\d{4}-\d{2}-\d{2}$/.test(row[3])) return 'Dates must be YYYY-MM-DD.';
    if (row[3] < row[2]) return `Delivery ${row[0]} is preferred before it was ordered.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const iso = (t) => new Date(t).toISOString().slice(0, 10);
  const start = Date.UTC(2019, 7, 1), day = 86400000;
  // Shuffle the ids so the table is not stored in id order.
  const ids = Array.from({ length: rows }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const share = small ? rand() : 0.2 + rand() * 0.6;
  const Delivery = ids.map((id) => {
    const ordered = start + Math.floor(rand() * (small ? 35 : 365)) * day;
    const wait = rand() < share ? 0 : 1 + Math.floor(rand() * 4);
    return [id, 1 + Math.floor(rand() * (small ? 4 : 300)), iso(ordered), iso(ordered + wait * day)];
  });
  return [{ Delivery }];
}
